export const code = async (inputs) => {
  const event = inputs.event || {};
  const lines = [];
  lines.push('Ты аналитик памяти проекта System2. По событию ниже реши, есть ли в нём');
  lines.push('устойчивое, переиспользуемое знание, которое стоит сохранить в память проекта.');
  lines.push('');
  lines.push('Ответ — только JSON, без пояснений и без markdown, ровно такой формы:');
  lines.push('{"has_pattern": true|false, "proposals": [{"category": "...", "status": "...", "scope": "...", "statement": "...", "evidence": "..."}]}');
  lines.push('');
  lines.push('Допустимые значения:');
  lines.push('  category: user-profile | facts | patterns | decisions | gotchas');
  lines.push('  status: observation | confirmed | superseded');
  lines.push('  scope: "user" или идентификатор проекта из события (' + (event.project_id || '') + ')');
  lines.push('statement и evidence — непустые строки в одну строку, без переводов строк.');
  lines.push('evidence — конкретная ссылка на факт события, не пересказ.');
  lines.push('Если устойчивого знания нет, верни {"has_pattern": false, "proposals": []}.');
  lines.push('');
  lines.push('--- СОБЫТИЕ ---');
  lines.push('event_id: ' + (event.event_id || ''));
  lines.push('project_id: ' + (event.project_id || ''));
  lines.push('kind: ' + (event.kind || ''));
  lines.push('summary: ' + (event.summary || ''));
  lines.push('decisions: ' + JSON.stringify(event.decisions || []));
  lines.push('user_corrections: ' + JSON.stringify(event.user_corrections || []));
  lines.push('checks: ' + JSON.stringify(event.checks || []));
  lines.push('next_action: ' + (event.next_action || ''));
  return { prompt: lines.join('\n') };
};

export const code = async (inputs) => {
  const CATEGORIES = ['user-profile', 'facts', 'patterns', 'decisions', 'gotchas'];
  const STATUSES = ['observation', 'confirmed', 'superseded'];
  const errors = [];
  const raw = inputs.response;
  let text = '';
  if (raw && Array.isArray(raw.content)) {
    text = raw.content
      .filter((block) => block && typeof block.text === 'string')
      .map((block) => block.text)
      .join('\n');
  } else if (raw && typeof raw.text === 'string') {
    text = raw.text;
  } else if (typeof raw === 'string') {
    text = raw;
  }
  let parsed = null;
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) {
    errors.push('AI response contains no JSON object');
  } else {
    try { parsed = JSON.parse(match[0]); } catch (e) { errors.push('AI response is not valid JSON: ' + e.message); }
  }
  if (parsed && typeof parsed.has_pattern !== 'boolean') errors.push('has_pattern must be a boolean');
  let proposals = [];
  const wantsProposals = parsed && parsed.has_pattern === true;
  if (wantsProposals) {
    if (!Array.isArray(parsed.proposals) || parsed.proposals.length === 0) {
      errors.push('proposals must be a non-empty array when has_pattern is true');
    } else {
      for (const p of parsed.proposals) {
        const one = (v) => typeof v === 'string' ? v.trim() : '';
        const category = p && p.category;
        const status = p && p.status;
        const scope = p && p.scope;
        const statement = one(p && p.statement);
        const evidence = one(p && p.evidence);
        if (!CATEGORIES.includes(category)) errors.push('invalid category: ' + category);
        if (!STATUSES.includes(status)) errors.push('invalid status: ' + status);
        if (scope !== 'user' && scope !== inputs.project_id) errors.push('scope must be "user" or the registered project_id: ' + scope);
        if (!statement || statement.includes('\n')) errors.push('statement must be a non-empty single line');
        if (!evidence || evidence.includes('\n')) errors.push('evidence must be a non-empty single line');
        if (statement.split('\n').some((line) => line.startsWith('---'))) errors.push('statement must not contain a line starting with ---');
        if (statement.length > 19000 || evidence.length > 19000) errors.push('statement/evidence too large');
      }
    }
  }
  const valid = errors.length === 0;
  const keep = valid && wantsProposals;
  return {
    valid: valid,
    errors: errors,
    has_pattern: keep,
    proposals: keep ? parsed.proposals.map((p) => ({
      category: p.category,
      status: p.status,
      scope: p.scope,
      statement: String(p.statement).trim(),
      evidence: String(p.evidence).trim(),
      source: 'activepieces-flow',
    })) : [],
  };
};

export const code = async (inputs) => {
  const eventId = inputs.event_id;
  const output = inputs.write_output;
  const detail = (value) => {
    if (value === undefined || value === null) return '';
    const text = typeof value === 'string' ? value : JSON.stringify(value);
    return String(text === undefined ? '' : text).slice(0, 500);
  };
  if (!output || typeof output !== 'object') {
    throw new Error('write produced no output');
  }
  if (output.response !== undefined) {
    const status = output.response ? output.response.status : undefined;
    const body = output.response ? output.response.body : undefined;
    if (status === 409) {
      return {
        body: {
          event_id: eventId,
          status: 'conflict',
          writer_status: 409,
          reason: 'writer rejected new proposals for an already persisted event_id',
          writer_body: detail(body),
        },
      };
    }
    throw new Error('write was not applied, HTTP ' + detail(status) + ': ' + detail(body));
  }
  const status = output.status;
  const body = output.body;
  if (typeof status === 'number' && status >= 200 && status < 300 && body && body.status === 'persisted') {
    return {
      body: {
        event_id: eventId,
        status: 'persisted',
        bridge: body,
        proposals: inputs.proposals,
      },
    };
  }
  throw new Error('unexpected write result: HTTP ' + detail(status) + ', body ' + detail(body));
};
